def compute(vars):
    balance_2019 = vars["v1"]
    balance_2018 = vars["v2"]
    change = balance_2019 - balance_2018

    return {
        "value": change,
        "trace": {
            "balance_2019": balance_2019,
            "balance_2018": balance_2018,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "monetary"
            }
        }
    }
